	if err != nil {
		return nil, apperr.Unauthenticated()
	}

	// 他人の User が解決された場合は、エラーではなく空配列を返す（design.md §6.8-#8）。
	//
	// エラーだと「そのユーザーは存在する」というシグナルになる。空配列なら
	// 「TODO を 1 件も持たない他人」と「他人なので見せない」が外形的に区別できない。
